```javascript
/**
 * @param {number} times
 * @return {string}
 */
String.prototype.replicate = function(times) {
    // In a non-strict method, `this` is a String wrapper object; convert to a primitive
    const s = String(this);
    if (times <= 0) return "";

    // Fill an array with `times` copies, then join once (avoids repeated reallocations)
    return new Array(times).fill(s).join("");
};
